mapper.insert:
/*
     SQL ID : MsgTmpltDAO.insertTmplt
     설  명 : 템플릿 등록
 */
INSERT INTO TB_LMS_MSG_TMPLT (
                               MSG_TMPLT_ID
                             , ORG_ID
                             , MSG_CTS_GBNCD
                             , MSG_TMPLT_TTL
                             , MSG_TMPLT_CTS
                             , RGTR_ID
                             , REG_DTTM
) VALUES (
           #{msgTmpltId}
         , #{orgId}
         , #{msgCtsGbncd}
         , #{msgTmpltTtl}
         , #{msgTmpltCts}
         , #{rgtrId}
         , FN_DTTM()
         )

mapper.update:
/*
     SQL ID : MsgTmpltDAO.updateTmplt
     설  명 : 템플릿 수정
 */
UPDATE TB_LMS_MSG_TMPLT
SET MSG_TMPLT_TTL = #{msgTmpltTtl}
, MSG_TMPLT_CTS = #{msgTmpltCts}
, MDFR_ID = #{mdfrId}
, MOD_DTTM = FN_DTTM()

    , MSG_CTS_GBNCD = #{msgCtsGbncd}

WHERE MSG_TMPLT_ID = #{msgTmpltId}

mapper.delete:
/*
     SQL ID : MsgTmpltDAO.deleteTmplt
     설  명 : 템플릿 삭제
 */
DELETE FROM TB_LMS_MSG_TMPLT
WHERE MSG_TMPLT_ID = #{msgTmpltId}

/*
     SQL ID : MsgTmpltDAO.deleteAllTmplt
     설  명 : 템플릿 전체 삭제
 */
DELETE FROM TB_LMS_MSG_TMPLT
WHERE ORG_ID = #{orgId}

  AND MSG_CTS_GBNCD = #{msgCtsGbncd}


  AND RGTR_ID = #{rgtrId}
